<template>
  <div class="fixed inset-0 z-[50] flex items-end justify-center">
    <!-- 原始相機背景（不吃點擊） -->
    <img
      v-if="imageData && imageData.originalImageData"
      :src="imageData.originalImageData"
      class="absolute inset-0 w-full h-full object-cover z-[1] pointer-events-none"
      style="transform: scaleX(-1)"
    />

    <!-- 月亮影片覆蓋層（不吃點擊） - 只在有人像時顯示 -->
    <div v-if="hasPerson" class="absolute inset-0 pointer-events-none z-[2]">
      <video
        ref="moonVideo"
        class="w-full h-full object-contain force-composite"
        autoplay
        loop
        muted
        playsinline
        webkit-playsinline
        style="pointer-events:none; background:transparent;"
        :src="moonVideoSrc"
      >
        <source v-if="isIOSDevice" :src="basePath + 'moon_alpha_ios.mov'" type="video/quicktime" />
        <source v-else :src="basePath + 'moon.webm'" type="video/webm" />
        <source :src="basePath + 'moon.mp4'" type="video/mp4" />
      </video>
    </div>

    <!-- 人像覆蓋層（不吃點擊） - 只在有人像且有分割數據時顯示 -->
    <img
      v-if="hasPerson && imageData && imageData.segmentedImageData"
      :src="imageData.segmentedImageData"
      class="absolute inset-0 w-full h-full object-cover z-[3] pointer-events-none"
    />

    <!-- 底部按鈕區域的半透明遮罩（不吃點擊） -->
    <div class="absolute bottom-0 left-0 right-0 h-32 bg-gradient-to-t from-black/80 to-transparent z-[4] pointer-events-none"></div>

   <!-- 確認按鈕區域（一定可點，拉最高 z） -->
    <div class="relative w-full p-4 sm:p-6 pb-6 sm:pb-8 z-[50] pointer-events-auto">
      <!-- 響應式按鈕容器 - 始終並排 -->
      <div class="mx-auto max-w-[600px] flex flex-row items-center justify-around px-2">
        <button
          @click="onRetake"
          class="flex-1 max-w-[150px] py-3 bg-white text-black rounded-[5px] font-medium text-[13px] sm:text-[15px]
                 border border-gray-300 hover:bg-gray-100 transition-colors
                 inline-flex items-center justify-center gap-1"
        >
          <span class="whitespace-nowrap">再拍一次</span>
          <!-- chevron-right svg -->
          <svg class="w-3 h-3 sm:w-4 sm:h-4" viewBox="0 0 24 24" fill="none"
               stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"
               aria-hidden="true" focusable="false">
            <polyline points="9 18 15 12 9 6" />
          </svg>
        </button>

        <button
          @click="onNext"
          class="flex-1 max-w-[150px] py-3 bg-white text-black rounded-[5px] font-medium text-[13px] sm:text-[15px]
                 border border-gray-300 hover:bg-gray-100 transition-colors
                 inline-flex items-center justify-center gap-1"
        >
          <span class="whitespace-nowrap">下一步</span>
          <!-- chevron-right svg -->
          <svg class="w-3 h-3 sm:w-4 sm:h-4" viewBox="0 0 24 24" fill="none"
               stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"
               aria-hidden="true" focusable="false">
            <polyline points="9 18 15 12 9 6" />
          </svg>
        </button>
      </div>
    </div>
  </div>
</template>

<script>
import { computed } from 'vue'

export default {
  name: 'CaptureConfirmation',
  props: {
    imageData: {
      type: Object,
      default: () => ({})
    },
    isIOSDevice: {
      type: Boolean,
      default: false
    },
    hasPerson: {
      type: Boolean,
      default: true
    }
  },
  emits: ['retake', 'next'],
  setup(props, { emit }) {
    const basePath = computed(() => import.meta.env.BASE_URL || '/')

    // iOS 裝置檢測
    const isIOSDevice = computed(() => {
      const userAgent = navigator.userAgent.toLowerCase()
      const isIOS = /iphone|ipad|ipod/.test(userAgent)
      const isLineApp = /line/.test(userAgent)
      const isChrome = /crios/.test(userAgent)
      const isSafari = /safari/.test(userAgent) && !/chrome/.test(userAgent)

      // 測試模式支援
      const urlParams = new URLSearchParams(window.location.search)
      const isTestMode = urlParams.get('test-mov') === '1'

      return (isIOS && (isLineApp || isChrome || isSafari)) || isTestMode
    })

    // 月亮影片來源（iOS 用 MOV，Android 用 WebM）
    const moonVideoSrc = computed(() => {
      return isIOSDevice.value
        ? basePath.value + 'moon_alpha_ios.mov'
        : basePath.value + 'moon.webm'
    })

    const onRetake = () => {
      emit('retake')
    }
    const onNext = () => {
      emit('next')
    }

    return {
      basePath,
      isIOSDevice,
      moonVideoSrc,
      onRetake,
      onNext,
      hasPerson: props.hasPerson
    }
  }
}
</script>