<template>
  <!-- 滿版預覽 -->
  <section
    class="fixed inset-0 bg-gray-900 overflow-hidden w-full h-full z-50 select-none"
    @touchstart="onTouchStart"
    @touchmove="onTouchMove"
    @touchend="onTouchEnd"
  >
    <!-- 背景（模糊 or 一般） -->
    <canvas ref="bgCanvas" class="absolute inset-0 block w-full h-full z-[5]" />
    <!-- 清晰區域 / 人像 -->
    <canvas ref="outputCanvas" class="absolute inset-0 block w-full h-full z-[20]" />

    <!-- 月亮 MOV（只在有人像時） -->
    <div v-if="hasPerson" class="absolute inset-0 pointer-events-none z-[15]" :style="contentAreaStyle">
      <video
        ref="moonVideoEl"
        class="w-full h-full object-contain force-composite"
        :src="moonVideoSrc"
        autoplay loop muted playsinline webkit-playsinline
        style="pointer-events:none; background:transparent; transform:translateZ(0); filter:opacity(1); backface-visibility:hidden;"
      >
        <source v-if="isIOSDevice" :src="basePath + 'moon_alpha_ios.mov'" type="video/quicktime" />
        <source v-else :src="basePath + 'moon.webm'" type="video/webm" />
        <source :src="basePath + 'moon.mp4'" type="video/mp4" />
      </video>
    </div>

    <!-- PNG 框（最上層顯示用；匯出時會再畫一次位圖） -->
    <div class="absolute inset-0 pointer-events-none z-[30]">
      <img
        v-if="currentBackground.frame"
        :src="basePath + currentBackground.frame"
        ref="frameImgEl"
        alt="裝飾框架"
        class="w-full h-full object-cover"
        style="pointer-events: none;"
        @error="handleFrameError"
        @load="handleFrameLoad"
      />
    </div>

    <!-- 日期與名字 -->
    <div class="absolute inset-0 pointer-events-none z-[35]">
      <div class="absolute text-white font-sans text-lg tracking-wider" :style="dateTextStyle">
        {{ currentDate }}
      </div>
      <div class="absolute text-white font-sans text-lg tracking-wider" :style="nameTextStyle">
        {{ userName || 'Guest' }}
      </div>
    </div>

    <!-- 處理中遮罩 -->
    <div v-if="isProcessing" class="absolute inset-0 flex items-center justify-center bg-black/50 z-[45]">
      <div class="text-white text-center">
        <div class="animate-spin rounded-full h-12 w-12 border-b-2 border-white mx-auto mb-4"></div>
        <p class="text-lg">合成中...</p>
      </div>
    </div>

    <!-- 底部控制列 -->
    <div
      v-show="!isProcessing"
      class="absolute left-0 right-0 z-[40] pt-4 pb-6"
      :style="{
        bottom: `calc(env(safe-area-inset-bottom,0px) + 36px)`,
        paddingBottom: `calc(1rem + env(safe-area-inset-bottom,0px))`
      }"
    >
      <!-- 輪播指示點（無論是否有人像都顯示；無人像代表切換框） -->
      <div class="flex items-center justify-center gap-2 mb-1">
        <span
          v-for="(bg, i) in availableBackgrounds"
          :key="bg.id || i"
          class="inline-block w-2.5 h-2.5 rounded-full transition-opacity"
          :class="i === currentBackgroundIndex ? 'bg-white' : 'bg-white/40'"
        />
      </div>

      <!-- 左右切換提示列（無論是否有人像都顯示） -->
      <div class="flex items-center justify-center mb-4">
        <button
          @click="prevBackground"
          class="grid place-items-center w-14 aspect-square rounded-full text-white active:scale-95 select-none"
          aria-label="上一個"
        >
          <svg class="w-7 h-7" viewBox="0 0 24 24" fill="none"
              stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <polyline points="15 18 9 12 15 6" />
          </svg>
        </button>

        <div
          class="px-4 py-1.5 rounded-full text-white/90 font-medium
                text-base md:text-lg tracking-[0.25em] select-none"
        >
          {{ hasPerson ? '左右點擊選取款式' : '左右點擊選取框架' }}
        </div>

        <button
          @click="nextBackground"
          class="grid place-items-center w-14 aspect-square rounded-full text-white active:scale-95 select-none"
          aria-label="下一個"
        >
          <svg class="w-7 h-7" viewBox="0 0 24 24" fill="none"
              stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <polyline points="9 18 15 12 9 6" />
          </svg>
        </button>
      </div>

      <!-- 下：操作按鈕 -->
      <div class="px-2 sm:px-6">
        <!-- 響應式按鈕容器 - 始終並排 -->
        <div class="mx-auto max-w-[600px] flex flex-row items-center justify-around">
          <button
            @click="downloadPhoto"
            class="flex-1 max-w-[180px] py-3 bg-white text-black rounded-[5px] font-medium text-[13px] sm:text-[15px]
                  border border-gray-300 hover:bg-gray-100 transition-colors inline-flex items-center justify-center gap-1"
          >
            <span class="whitespace-nowrap">收藏探月護照</span>
            <svg class="w-3 h-3 sm:w-4 sm:h-4" viewBox="0 0 24 24" fill="none"
                stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="9 18 15 12 9 6" />
            </svg>
          </button>

          <button
            @click="sharePhoto"
            class="flex-1 max-w-[180px] py-3 bg-white text-black rounded-[5px] font-medium text-[15px] sm:text-[15px]
                  border border-gray-300 hover:bg-gray-100 transition-colors inline-flex items-center justify-center gap-1"
          >
            <span class="whitespace-nowrap">分享給好友</span>
            <svg class="w-3 h-3 sm:w-4 sm:h-4" viewBox="0 0 24 24" fill="none"
                stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="9 18 15 12 9 6" />
            </svg>
          </button>
        </div>
      </div>
    </div>

    <!-- 隱藏元素 -->
    <div class="hidden">
      <video ref="bgMoonVideoEl" class="bg_video" muted loop preload="auto" playsinline style="display: none;" />
    </div>
  </section>
</template>

<script>
import { ref, computed, onMounted, onBeforeUnmount, nextTick } from 'vue'

export default {
  name: 'PhotoPreview',
  props: {
    originalImageData: { type: [String, Object], required: true },
    availableBackgrounds: { type: Array, required: true },
    selectedBackground: { type: String, required: true },
    userName: { type: String, default: '' },
    hasPerson: { type: Boolean, default: true }
  },
  emits: ['close', 'background-change'],
  setup(props, { emit }) {
    // Refs
    const bgCanvas = ref(null)
    const outputCanvas = ref(null)
    const moonVideoEl = ref(null)
    const bgMoonVideoEl = ref(null)
    const frameImgEl = ref(null)

    // State
    const isProcessing = ref(false)
    const currentBackgroundIndex = ref(0)

    // Base path
    const basePath = computed(() => import.meta.env.BASE_URL || '/')

    // iOS 裝置檢測
    const isIOSDevice = computed(() => {
      const userAgent = navigator.userAgent.toLowerCase()
      const isIOS = /iphone|ipad|ipod/.test(userAgent)
      const isLineApp = /line/.test(userAgent)
      const isChrome = /crios/.test(userAgent)
      const isSafari = /safari/.test(userAgent) && !/chrome/.test(userAgent)

      // 測試模式支援
      const urlParams = new URLSearchParams(window.location.search)
      const isTestMode = urlParams.get('test-mov') === '1'

      return (isIOS && (isLineApp || isChrome || isSafari)) || isTestMode
    })

    // 月亮影片來源（iOS 用 MOV，Android 用 WebM）
    const moonVideoSrc = computed(() => {
      return isIOSDevice.value
        ? basePath.value + 'moon_alpha_ios.mov'
        : basePath.value + 'moon.webm'
    })

    // Background
    const currentBackground = computed(() => {
      return props.availableBackgrounds[currentBackgroundIndex.value] || props.availableBackgrounds[0]
    })

    // Constants
    const BLUR_PX         = 6
    const MOON_OFFSET_PCT = 0.06
    const DATE_X_IN_FRAME = 0.182
    const DATE_Y_IN_FRAME = 0.695
    const NAME_X_IN_FRAME = 0.530
    const NAME_Y_IN_FRAME = 0.695
    const TEXT_SIZE_PX    = 18

    // 尺寸 + 框天然尺寸
    const viewport = ref({ w: 0, h: 0 })
    const updateViewport = () => {
      viewport.value.w = window.innerWidth || 0
      viewport.value.h = window.innerHeight || 0
    }
    const frameNatural = ref({ w: 0, h: 0 })
    const handleFrameLoad = (e) => {
      const img = e?.target || frameImgEl.value
      if (!img) return
      frameNatural.value = { w: img.naturalWidth || 0, h: img.naturalHeight || 0 }
      updateViewport()
      renderPreview()
    }
    const handleFrameError = (e) => {
      // 框架載入失敗時的靜默處理
    }

    onMounted(() => {
      updateViewport()
      window.addEventListener('resize', onResize)

      nextTick(() => {
        if (bgMoonVideoEl.value) {
          bgMoonVideoEl.value.src = basePath.value + 'moon.mp4'
        }
        setTimeout(initPreview, 50)
      })
    })
    onBeforeUnmount(() => {
      window.removeEventListener('resize', onResize)
      if (moonVideoEl.value && !moonVideoEl.value.paused) {
        moonVideoEl.value.pause()
      }
    })
    const onResize = () => {
      updateViewport()
      renderPreview()
    }

    // 工具：計算 object-cover 後的實際顯示矩形
    function coverRect (W, H, mediaW, mediaH) {
      if (!W || !H || !mediaW || !mediaH) return { x: 0, y: 0, w: W, h: H }
      const scale = Math.max(W / mediaW, H / mediaH)
      const w = Math.round(mediaW * scale)
      const h = Math.round(mediaH * scale)
      return { x: Math.round((W - w) / 2), y: Math.round((H - h) / 2), w, h }
    }

    // 日期/名字定位（相對 PNG 框）
    const currentDate = computed(() => {
      const now = new Date()
      return `${now.getFullYear()}.${String(now.getMonth()+1).padStart(2,'0')}.${String(now.getDate()).padStart(2,'0')}`
    })
    const dateTextStyle = computed(() => {
      const W = viewport.value.w, H = viewport.value.h
      const fw = frameNatural.value.w, fh = frameNatural.value.h
      const rect = coverRect(W, H, fw, fh)
      const x = rect.x + rect.w * DATE_X_IN_FRAME
      const y = rect.y + rect.h * DATE_Y_IN_FRAME
      return { position:'absolute', top:0, left:0, transform:`translate(${x}px,${y}px)`, fontSize:`${TEXT_SIZE_PX}px`, whiteSpace:'nowrap', textShadow:'0 1px 2px rgba(0,0,0,.6)' }
    })
    const nameTextStyle = computed(() => {
      const W = viewport.value.w, H = viewport.value.h
      const fw = frameNatural.value.w, fh = frameNatural.value.h
      const rect = coverRect(W, H, fw, fh)
      const x = rect.x + rect.w * NAME_X_IN_FRAME
      const y = rect.y + rect.h * NAME_Y_IN_FRAME
      return { position:'absolute', top:0, left:0, transform:`translate(${x}px,${y}px)`, fontSize:`${TEXT_SIZE_PX}px`, whiteSpace:'nowrap', textShadow:'0 1px 2px rgba(0,0,0,.6)' }
    })

    // 月亮影片 DOM 區域（依 contentArea + moonScale）
    const contentAreaStyle = computed(() => {
      const area = currentBackground.value?.contentArea
      if (!area) return {}
      const moonScale = currentBackground.value.moonScale || 1.0
      const W = viewport.value.w
      const H = viewport.value.h
      const baseW = area.width  * W
      const baseH = area.height * H
      const baseL = area.x * W
      const baseT = area.y * H
      const scaledW = baseW * moonScale
      const scaledH = baseH * moonScale
      const scaledL = baseL - (scaledW - baseW) / 2
      const scaledT = baseT - (scaledH - baseH) / 2
      return {
        left: `${scaledL}px`,
        top: `${scaledT + H * MOON_OFFSET_PCT}px`,
        width: `${scaledW}px`,
        height: `${scaledH}px`
      }
    })

    // 初始化
    const initPreview = async () => {
      if (!bgCanvas.value || !outputCanvas.value) return
      try {
        isProcessing.value = true
        await renderPreview()
        if (props.hasPerson && moonVideoEl.value) {
          try { await moonVideoEl.value.play() } catch {}
        }
      } catch (e) {
        // 預覽初始化失敗時的靜默處理
      } finally {
        isProcessing.value = false
      }
    }

    // 背景/框切換：無人像時切換「框」與 contentArea；有人像時同時也會換背景圖
    const switchBackground = async (dir = 1) => {
      const total = props.availableBackgrounds.length || 1
      currentBackgroundIndex.value = (currentBackgroundIndex.value + dir + total) % total
      emit('background-change', currentBackground.value.id)
      await renderPreview()
    }
    const prevBackground = () => switchBackground(-1)
    const nextBackground = () => switchBackground(1)

    // 觸控滑動切換（無論是否有人像都可用）
    const touch = { x0: 0, y0: 0, moving: false }
    const onTouchStart = (e) => {
      const t = e.touches?.[0]
      if (!t) return
      touch.x0 = t.clientX
      touch.y0 = t.clientY
      touch.moving = true
    }
    const onTouchMove = () => {}
    const onTouchEnd = (e) => {
      if (!touch.moving) return
      touch.moving = false
      const t = e.changedTouches?.[0]
      if (!t) return
      const dx = t.clientX - touch.x0
      const dy = t.clientY - touch.y0
      if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy)) {
        dx < 0 ? nextBackground() : prevBackground()
      }
    }

    // 繪製預覽
    const renderPreview = async () => {
      const bgCtx = bgCanvas.value.getContext('2d')
      const outCtx = outputCanvas.value.getContext('2d')
      const W = window.innerWidth
      const H = window.innerHeight
      bgCanvas.value.width = outputCanvas.value.width = W
      bgCanvas.value.height = outputCanvas.value.height = H

      bgCtx.clearRect(0,0,W,H)
      outCtx.clearRect(0,0,W,H)

      if (props.hasPerson) {
        // 背景：使用背景圖
        if (currentBackground.value?.src) {
          try {
            const bgImg = await loadImageSafe(basePath.value + currentBackground.value.src)
            if (bgImg) { bgCtx.drawImage(bgImg, 0, 0, W, H) }
            else { bgCtx.fillStyle = '#1a1a1a'; bgCtx.fillRect(0,0,W,H) }
          } catch {
            bgCtx.fillStyle = '#1a1a1a'; bgCtx.fillRect(0,0,W,H)
          }
        } else {
          bgCtx.fillStyle = '#1a1a1a'; bgCtx.fillRect(0,0,W,H)
        }

        // 人像
        let imageData = props.originalImageData
        if (typeof imageData === 'object' && imageData?.segmentedImageData) {
          imageData = imageData.segmentedImageData
        } else if (typeof imageData === 'object' && imageData?.originalImageData) {
          imageData = imageData.originalImageData
        }
        if (imageData) {
          try {
            const personImg = await loadImageSafe(imageData)
            if (personImg) {
              const area = currentBackground.value.contentArea || { x:0, y:0, width:1, height:1 }
              const rect = { x: area.x * W, y: area.y * H, w: area.width * W, h: area.height * H }
              drawContain(outCtx, personImg, rect.x, rect.y, rect.w, rect.h)
            }
          } catch (e) { /* 人像載入失敗時的靜默處理 */ }
        }
      } else {
        // 無人像：背景使用拍照原圖（水平反轉修正），框與 contentArea 可切換
        let originalSrc = props.originalImageData
        if (typeof originalSrc === 'object' && originalSrc?.originalImageData) {
          originalSrc = originalSrc.originalImageData
        }
        const originalImg = await loadImageSafe(originalSrc)
        if (!originalImg) {
          bgCtx.fillStyle = '#1a1a1a'; bgCtx.fillRect(0,0,W,H)
        } else {
          const cover = coverRect(W, H, originalImg.naturalWidth, originalImg.naturalHeight)
          const drawCovered = (ctx) => {
            const destX = W - (cover.x + cover.w) // 水平反轉對齊
            ctx.drawImage(
              originalImg,
              0, 0, originalImg.naturalWidth, originalImg.naturalHeight,
              destX, cover.y, cover.w, cover.h
            )
          }
          // 模糊底
          bgCtx.save()
          bgCtx.filter = `blur(${BLUR_PX}px)`
          bgCtx.translate(W, 0)
          bgCtx.scale(-1, 1)
          drawCovered(bgCtx)
          bgCtx.restore()

          // 清晰框內（依目前選到的框 contentArea）
          const area = currentBackground.value?.contentArea || { x: 0.05, y: 0.25, width: 0.9, height: 0.5 }
          const clearRect = { x: area.x * W, y: area.y * H, w: area.width * W, h: area.height * H }

          outCtx.save()
          outCtx.beginPath()
          outCtx.rect(clearRect.x, clearRect.y, clearRect.w, clearRect.h)
          outCtx.clip()
          outCtx.translate(W, 0)
          outCtx.scale(-1, 1)
          drawCovered(outCtx)
          outCtx.restore()
        }
      }
      // PNG 框由 <img> 顯示（匯出時位圖化）
    }

    // ===== 匯出：無人像→圖片；有人像→影片 =====
    const generatePreviewImage = async () => {
      const cssW = Math.round(window.innerWidth)
      const cssH = Math.round(window.innerHeight)
      const dpr = Math.min(window.devicePixelRatio || 1, 2)
      const canvas = document.createElement('canvas')
      canvas.width = Math.round(cssW * dpr)
      canvas.height = Math.round(cssH * dpr)
      const ctx = canvas.getContext('2d')
      ctx.scale(dpr, dpr)

      // 素材
      let originalSrc = props.originalImageData
      if (typeof originalSrc === 'object' && originalSrc?.originalImageData) originalSrc = originalSrc.originalImageData
      const originalImg = await loadImageSafe(originalSrc)
      const frameImg = await loadImageSafe(currentBackground.value?.frame ? basePath.value + currentBackground.value.frame : null)

      drawOneFrame(ctx, cssW, cssH, {
        bgImg: null, frameImg, personImg: null, originalImg, moonVid: null,
        personRect: { x:0,y:0,w:0,h:0 }, moonRect: { x:0,y:0,w:0,h:0 },
        hasPerson: false, flipHorizontal: true
      })

      const blob = await new Promise(res => canvas.toBlob(res, 'image/png', 1))
      const url = URL.createObjectURL(blob)
      return { blob, url, mime: 'image/png', fileName: `range_rover_preview_${Date.now()}.png` }
    }

    const generatePreviewVideo = async (durationMs = 5000) => {
      isProcessing.value = true
      try {
        const cssW = Math.round(window.innerWidth)
        const cssH = Math.round(window.innerHeight)
        const dpr = Math.min(window.devicePixelRatio || 1, 2)
        const canvas = document.createElement('canvas')
        canvas.width = Math.round(cssW * dpr)
        canvas.height = Math.round(cssH * dpr)
        const ctx = canvas.getContext('2d')
        ctx.scale(dpr, dpr)

        const stream = canvas.captureStream(30)
        const mime = pickMimeType([
          'video/mp4;codecs=h264', 'video/mp4',
          'video/webm;codecs=vp9', 'video/webm;codecs=vp8', 'video/webm'
        ])
        if (!mime) throw new Error('此瀏覽器不支援 MediaRecorder 錄製影片')

        const chunks = []
        const rec = new MediaRecorder(stream, { mimeType: mime, videoBitsPerSecond: 6_000_000 })
        rec.ondataavailable = e => e.data && e.data.size && chunks.push(e.data)
        const done = new Promise(res => {
          rec.onstop = () => {
            const type = mime.includes('mp4') ? 'video/mp4' : 'video/webm'
            const blob = new Blob(chunks, { type })
            const url = URL.createObjectURL(blob)
            res({ blob, url, mime: type, fileName: `range_rover_preview_${Date.now()}.${type.includes('mp4')?'mp4':'webm'}` })
          }
        })

        // 素材（有人像）
        const frameImg = await loadImageSafe(currentBackground.value?.frame ? basePath.value + currentBackground.value.frame : null)
        const bgImg = await loadImageSafe(currentBackground.value?.src ? basePath.value + currentBackground.value.src : null)
        let personSrc = props.originalImageData
        if (typeof personSrc === 'object' && personSrc?.segmentedImageData) personSrc = personSrc.segmentedImageData
        else if (typeof personSrc === 'object' && personSrc?.originalImageData) personSrc = personSrc.originalImageData
        const personImg = await loadImageSafe(personSrc)

        const moonVid = moonVideoEl.value
        if (moonVid) { await ensureVideoReady(moonVid); try { await moonVid.play() } catch {} }

        const area = currentBackground.value?.contentArea || { x:0, y:0, width:1, height:1 }
        const personRect = { x: area.x*cssW, y: area.y*cssH, w: area.width*cssW, h: area.height*cssH }
        const moonScale = currentBackground.value?.moonScale || 1
        const moonRect = {
          w: personRect.w * moonScale, h: personRect.h * moonScale,
          x: personRect.x - (personRect.w * (moonScale - 1))/2,
          y: personRect.y - (personRect.h * (moonScale - 1))/2 + cssH * MOON_OFFSET_PCT
        }

        rec.start(100)
        const start = performance.now()
        const loop = () => {
          const now = performance.now()
          drawOneFrame(ctx, cssW, cssH, {
            bgImg, frameImg, personImg, originalImg: null, moonVid,
            personRect, moonRect, hasPerson: true, flipHorizontal: false
          })
          if (now - start < durationMs) requestAnimationFrame(loop)
          else rec.stop()
        }
        drawOneFrame(ctx, cssW, cssH, {
          bgImg, frameImg, personImg, originalImg: null, moonVid,
          personRect, moonRect, hasPerson: true, flipHorizontal: false
        })
        requestAnimationFrame(loop)

        return await done
      } finally {
        isProcessing.value = false
      }
    }

    // 下載
    const downloadPhoto = async () => {
      try {
        if (props.hasPerson) {
          const { url, fileName } = await generatePreviewVideo(5000)
          const a = document.createElement('a'); a.download = fileName; a.href = url; a.click()
          setTimeout(() => { try { URL.revokeObjectURL(url) } catch {} }, 5000)
        } else {
          const { url, fileName } = await generatePreviewImage()
          const a = document.createElement('a'); a.download = fileName; a.href = url; a.click()
          setTimeout(() => { try { URL.revokeObjectURL(url) } catch {} }, 5000)
        }
      } catch (e) { alert('下載失敗，請重試') }
    }

    // 分享
    const sharePhoto = async () => {
      // Web Share API 需要 HTTPS 環境
      try {
        if (navigator.share) {
          if (props.hasPerson) {
            const r = await generatePreviewVideo(3000)
            const file = new File([r.blob], r.fileName, { type: r.mime })
            try {
              if (navigator.canShare?.({ files: [file] }) || !navigator.canShare) {
                await navigator.share({ files: [file], title: 'Range Rover 月圓節', text: '我的月圓節影片' })
                return
              }
            } catch {}
            await navigator.share({ title: 'Range Rover 月圓節', text: '我的月圓節影片', url: r.url })
            setTimeout(() => { try { URL.revokeObjectURL(r.url) } catch {} }, 15000)
            return
          } else {
            const r = await generatePreviewImage()
            const file = new File([r.blob], r.fileName, { type: 'image/png' })
            try {
              if (navigator.canShare?.({ files: [file] }) || !navigator.canShare) {
                await navigator.share({ files: [file], title: 'Range Rover 月圓節', text: '我的月圓節照片' })
                return
              }
            } catch {}
            await navigator.share({ title: 'Range Rover 月圓節', text: '我的月圓節照片', url: r.url })
            setTimeout(() => { try { URL.revokeObjectURL(r.url) } catch {} }, 15000)
            return
          }
        }
        await downloadPhoto()
      } catch (e) {
        alert('無法分享，已改為下載')
        try { await downloadPhoto() } catch {}
      }
    }

    // 小工具
    const pickMimeType = (cands) => { for (const t of cands) { try { if (MediaRecorder.isTypeSupported(t)) return t } catch {} } return '' }
    const ensureVideoReady = v => new Promise(res => {
      if (!v) return res(); if (v.readyState >= 2) return res()
      const onReady = () => { v.removeEventListener('loadeddata', onReady); v.removeEventListener('canplay', onReady); res() }
      v.addEventListener('loadeddata', onReady, { once:true }); v.addEventListener('canplay', onReady, { once:true })
    })
    const loadImageSafe = (src) => new Promise(resolve => {
      if (!src) return resolve(null); const img = new Image(); img.crossOrigin='anonymous'
      img.onload = () => resolve(img); img.onerror = () => resolve(null); img.src = src
    })
    const drawContain = (ctx, media, x, y, w, h) => {
      const mw = media.videoWidth || media.naturalWidth || w
      const mh = media.videoHeight || media.naturalHeight || h
      if (!mw || !mh) return
      const scale = Math.min(w/mw, h/mh)
      const dw = mw*scale, dh = mh*scale
      const dx = x + (w-dw)/2, dy = y + (h-dh)/2
      try { ctx.drawImage(media, 0,0,mw,mh, dx,dy,dw,dh) } catch {}
    }
    const drawCover = (ctx, img, x, y, w, h) => {
      const mw = img?.naturalWidth || w, mh = img?.naturalHeight || h
      if (!mw || !mh) return
      const scale = Math.max(w/mw, h/mh), dw = mw*scale, dh = mh*scale
      const dx = x + (w-dw)/2, dy = y + (h-dh)/2
      try { ctx.drawImage(img, 0,0,mw,mh, dx,dy,dw,dh) } catch {}
    }
    const drawOneFrame = (ctx, W, H, { bgImg, frameImg, personImg, originalImg, moonVid, personRect, moonRect, hasPerson, flipHorizontal=false }) => {
      ctx.clearRect(0,0,W,H)

      if (hasPerson) {
        if (bgImg) { try { ctx.drawImage(bgImg,0,0,W,H) } catch { ctx.fillStyle='#1a1a1a'; ctx.fillRect(0,0,W,H) } }
        else { ctx.fillStyle='#1a1a1a'; ctx.fillRect(0,0,W,H) }
        if (moonVid && moonVid.readyState >= 2) drawContain(ctx, moonVid, moonRect.x, moonRect.y, moonRect.w, moonRect.h)
        if (personImg) drawContain(ctx, personImg, personRect.x, personRect.y, personRect.w, personRect.h)
      } else {
        if (originalImg) {
          const cover = coverRect(W, H, originalImg.naturalWidth, originalImg.naturalHeight)
          // 模糊底
          ctx.save()
          ctx.filter = `blur(${BLUR_PX}px)`
          if (flipHorizontal) { ctx.translate(W,0); ctx.scale(-1,1) }
          const destX = flipHorizontal ? W - (cover.x + cover.w) : cover.x
          ctx.drawImage(originalImg, 0,0, originalImg.naturalWidth, originalImg.naturalHeight, destX, cover.y, cover.w, cover.h)
          ctx.restore()
          // 清晰框內
          const area = currentBackground.value?.contentArea || { x: 0.05, y: 0.25, width: 0.9, height: 0.5 }
          const clearRect = { x: area.x * W, y: area.y * H, w: area.width * W, h: area.height * H }
          ctx.save()
          ctx.beginPath()
          ctx.rect(clearRect.x, clearRect.y, clearRect.w, clearRect.h)
          ctx.clip()
          if (flipHorizontal) { ctx.translate(W,0); ctx.scale(-1,1) }
          const destX2 = flipHorizontal ? W - (cover.x + cover.w) : cover.x
          ctx.drawImage(originalImg, 0,0, originalImg.naturalWidth, originalImg.naturalHeight, destX2, cover.y, cover.w, cover.h)
          ctx.restore()
        } else {
          ctx.fillStyle='#1a1a1a'; ctx.fillRect(0,0,W,H)
        }
      }

      // 框
      if (frameImg) drawCover(ctx, frameImg, 0,0,W,H)

      // 文字（相對框）
      ctx.font = `${TEXT_SIZE_PX}px "Land Rover Web", sans-serif`
      ctx.fillStyle = '#fff'
      ctx.textBaseline = 'top'
      ctx.textAlign = 'left'
      ctx.shadowColor = 'rgba(0,0,0,.6)'
      ctx.shadowBlur = 2
      ctx.shadowOffsetY = 1
      if (frameImg?.naturalWidth && frameImg?.naturalHeight) {
        const rect = coverRect(W, H, frameImg.naturalWidth, frameImg.naturalHeight)
        ctx.fillText(currentDate.value, rect.x + rect.w*DATE_X_IN_FRAME, rect.y + rect.h*DATE_Y_IN_FRAME)
        ctx.fillText(props.userName || 'Guest', rect.x + rect.w*NAME_X_IN_FRAME, rect.y + rect.h*NAME_Y_IN_FRAME)
      }
      ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0; ctx.shadowOffsetY = 0
    }

    return {
      // Refs
      bgCanvas, outputCanvas, moonVideoEl, bgMoonVideoEl, frameImgEl,
      // State
      isProcessing, currentBackgroundIndex,
      // Data
      basePath, currentBackground, currentDate, contentAreaStyle, dateTextStyle, nameTextStyle,
      // Device Detection
      isIOSDevice, moonVideoSrc,
      // Props
      hasPerson: props.hasPerson,
      // Actions
      prevBackground, nextBackground, downloadPhoto, sharePhoto,
      // Touch
      onTouchStart, onTouchMove, onTouchEnd,
      // Debug
      handleFrameLoad, handleFrameError
    }
  }
}
</script>