<template>
  <div class="landing-page relative overflow-hidden w-screen h-screen">
    <!-- 背景圖片 -->
    <div
      ref="bgContainer"
      class="absolute inset-0 w-full h-full bg-cover bg-top bg-no-repeat"
      :style="{ backgroundImage: `url(${basePath}backgrounds/liffEntranceBg.png)` }"
    ></div>

    <!-- 疊加圖片 -->
    <div
      class="absolute inset-0 w-full h-full bg-contain bg-top bg-no-repeat"
      :style="{ backgroundImage: `url(${basePath}backgrounds/merged.png)` }"
    ></div>

    <!-- 透明輸入框 - 動態響應式定位 -->
    <div
      class="absolute"
      :style="inputBoxStyle"
    >
      <input
        v-model="userName"
        type="text"
        placeholder="輸 入 車 主 名 稱"
        class="w-full h-full px-2 sm:px-4 text-center bg-transparent border-none text-white placeholder-white/80 focus:outline-none focus:placeholder-white/60 transition-all text-base sm:text-lg"
        @keyup.enter="startCamera"
      />
    </div>

    <!-- 開啟相機按鈕 - 動態響應式定位 -->
    <button
      @click="startCamera"
      class="absolute flex items-center justify-center bg-transparent border-none text-transparent transition-all cursor-pointer z-10"
      style="outline: none; -webkit-tap-highlight-color: transparent;"
      :style="buttonStyle"
    >
      <!-- 透明點擊區域，按鈕視覺效果由背景圖提供 -->
    </button>

    <!-- 質感提醒訊息 -->
    <div
      v-if="showReminder"
      class="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-40 backdrop-blur-sm"
    >
      <div class="bg-white bg-opacity-90 backdrop-blur-md rounded-lg px-8 py-6 mx-6 text-center shadow-2xl transform transition-all duration-300"
           :class="{ 'scale-100 opacity-100': showReminder, 'scale-95 opacity-0': !showReminder }">
        <div class="text-gray-800 text-lg font-medium">
          請先輸入車主名稱！
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'

export default {
  name: 'LandingPage',
  emits: ['start-camera'],
  setup(props, { emit }) {
    const userName = ref('')
    const basePath = computed(() => import.meta.env.BASE_URL || '/')
    const showReminder = ref(false)
    const screenSize = ref({ width: window.innerWidth, height: window.innerHeight })

    // 瀏覽器偵測
    const isLineApp = computed(() => {
      const ua = navigator.userAgent.toLowerCase()
      return /line/.test(ua)
    })

    const isIOSDevice = computed(() => {
      const ua = navigator.userAgent.toLowerCase()
      return /iphone|ipad|ipod/.test(ua)
    })

    // LINE 瀏覽器專用調整
    const lineAdjustment = computed(() => {
      if (!isLineApp.value) return { x: 0, y: 0 }

      // LINE 在不同設備上的偏移調整 - 調低一個輸入框高度(約6.77vh)
      if (isIOSDevice.value) {
        return { x: 0, y: 6.77 } // iOS LINE 向下偏移約一個輸入框高度
      } else {
        return { x: 0, y: 6.77 } // Android LINE 向下偏移約一個輸入框高度
      }
    })

    // 動態計算輸入框位置
    const inputBoxStyle = computed(() => {
      const baseLeft = 16.90
      const baseTop = 54.98
      const baseWidth = 66.21
      const baseHeight = 6.77

      if (isLineApp.value) {
        // LINE 瀏覽器使用 vh/vw 單位並加上調整
        return {
          left: `${baseLeft}vw`,
          top: `calc(${baseTop}vh + ${lineAdjustment.value.y}vh)`,
          width: `${baseWidth}vw`,
          height: `${baseHeight}vh`
        }
      } else {
        // 其他瀏覽器使用百分比
        return {
          left: `${baseLeft}%`,
          top: `${baseTop}%`,
          width: `${baseWidth}%`,
          height: `${baseHeight}%`
        }
      }
    })

    // 動態計算按鈕位置
    const buttonStyle = computed(() => {
      const baseLeft = 20.03
      const baseTop = 76.82
      const baseWidth = 60.07
      const baseHeight = 6.71

      if (isLineApp.value) {
        // LINE 瀏覽器使用 vh/vw 單位並加上調整
        return {
          left: `${baseLeft}vw`,
          top: `calc(${baseTop}vh + ${lineAdjustment.value.y}vh)`,
          width: `${baseWidth}vw`,
          height: `${baseHeight}vh`
        }
      } else {
        // 其他瀏覽器使用百分比
        return {
          left: `${baseLeft}%`,
          top: `${baseTop}%`,
          width: `${baseWidth}%`,
          height: `${baseHeight}%`
        }
      }
    })

    const startCamera = () => {
      if (userName.value.trim()) {
        emit('start-camera', userName.value.trim())
      } else {
        showReminder.value = true
        // 兩秒後自動淡出
        setTimeout(() => {
          showReminder.value = false
        }, 2000)
      }
    }

    const hideReminder = () => {
      showReminder.value = false
    }

    // 更新螢幕尺寸
    const updateScreenSize = () => {
      screenSize.value = {
        width: window.innerWidth,
        height: window.innerHeight
      }
    }

    // 生命周期管理
    onMounted(() => {
      window.addEventListener('resize', updateScreenSize)
      window.addEventListener('orientationchange', updateScreenSize)

      // 針對 LINE 瀏覽器的特殊處理
      if (isLineApp.value) {
        console.log('LINE 瀏覽器偵測到，啟用專用定位策略')
        // 延遲執行以確保視窗尺寸正確
        setTimeout(updateScreenSize, 100)
      }
    })

    onBeforeUnmount(() => {
      window.removeEventListener('resize', updateScreenSize)
      window.removeEventListener('orientationchange', updateScreenSize)
    })

    return {
      userName,
      basePath,
      showReminder,
      inputBoxStyle,
      buttonStyle,
      isLineApp,
      startCamera,
      hideReminder
    }
  }
}
</script>

<style scoped>
/* 移除舊的背景樣式，現在使用動態背景圖片 */
</style>