<template>
  <!-- 改這行：固定定位 + 直接吃動態 viewport 尺寸 -->
  <section
    ref="stage"
    class="stage fixed inset-0 bg-gray-900 overflow-hidden w-[100dvw] h-[100dvh]"
    style="width:100vw;width:100dvw;height:100vh;height:100dvh"
  >
    <!-- 三張 Canvas 依舊鋪滿容器 -->
    <canvas ref="bgCanvas"    class="bg_canvas absolute inset-0 block w-full h-full z-[5]" />
    <canvas ref="maskCanvas"  class="mask_canvas absolute inset-0 block w-full h-full z-[10]" />
    
    <!-- 月亮影片 - 只在相機運行時顯示 -->
    <div class="absolute inset-0 pointer-events-none z-[10]">
      <video
        ref="moonVideo"
        v-show="cameraRunning && ['moon_video','custom_moon_bg','person_overlay'].includes(backgroundType)"
        class="w-full h-full object-contain force-composite"
        autoplay
        loop
        muted
        playsinline
        webkit-playsinline
        style="pointer-events:none; background:transparent;"
        :src="moonVideoSrc"
      >
        <source v-if="isIOSDevice" :src="basePath + 'moon_alpha_ios.mov'" type="video/quicktime" />
        <source v-else :src="basePath + 'moon.webm'" type="video/webm" />
        <source :src="basePath + 'moon.mp4'" type="video/mp4" />
      </video>
    </div>
    
    <canvas ref="outputCanvas" class="output_canvas absolute inset-0 block w-full h-full" :class="showControls ? 'z-[100]' : 'z-[10]'" />

    <!-- 相機啟動中載入提示 -->
    <div v-show="showControls && !cameraRunning" 
         class="absolute inset-0 flex items-center justify-center z-[120] bg-gray-900 bg-opacity-80">
      <div class="text-center text-white">
        <div class="animate-spin rounded-full h-8 w-8 border-b-2 border-white mx-auto mb-4"></div>
        <p class="text-lg">相機啟動中...</p>
      </div>
    </div>

    <!-- 底部快門（只在相機運行且控制可見時顯示） -->
    <button
      v-show="showControls && cameraRunning"
      @click="$emit('capture-photo')"
      class="absolute bottom-12 sm:bottom-16 left-1/2 -translate-x-1/2 z-[110]
            flex items-center justify-center
            w-[80px] h-[80px] sm:w-[99px] sm:h-[99px]"
    >
      <img
        :src="shutterIcon"
        alt="拍照"
        class="w-full h-full max-w-none select-none pointer-events-none"
      />
    </button>

    <!-- 提示文字（只在相機運行且控制可見時顯示） -->
    <div
      v-show="showControls && cameraRunning && showHintText"
      class="absolute bottom-8 sm:bottom-12 left-1/2 -translate-x-1/2 z-[110]
            text-white text-center font-medium
            text-[16px] tracking-[0.18em]
            transition-opacity duration-500
            whitespace-nowrap px-4"
      :class="{ 'opacity-0': !hintVisible }"
      :style="{
        textShadow: '0 2px 8px rgba(0,0,0,.55)',
        transform: `translate(-50%, 0) scale(${textScale})`,
        transformOrigin: 'center center'
      }"
    >
      對準臉部拍照可解鎖彩蛋
    </div>
  </section>
</template>

<script>
import { ref, computed, onMounted, onBeforeUnmount, watch, toRefs } from 'vue'
import shutterIcon from '@/assets/images/shutter.png'

export default {
  name: 'CameraStage',
  props: {
    backgroundType: { type: String, default: '' },
    isIOSDevice:   { type: Boolean, default: false },
    showControls:  { type: Boolean, default: true },
    cameraRunning: { type: Boolean, default: false }
  },
  emits: ['capture-photo', 'share-video', 'download-video'],
  setup(props, { expose }) {
    const { showControls, cameraRunning } = toRefs(props)
    
    const stage        = ref(null)
    const bgCanvas     = ref(null)
    const maskCanvas   = ref(null)
    const outputCanvas = ref(null)
    const moonVideo    = ref(null)

    const showShareButton    = ref(false)
    const showDownloadButton = ref(false)
    const showHintText = ref(true)
    const hintVisible  = ref(true)

    // 動態文字縮放以防止換行
    const textScale = ref(1)

    const calculateTextScale = () => {
      const screenWidth = window.innerWidth
      const textWidth = 280 // 大約估算「對準臉部拍照可解鎖彩蛋」的寬度（含間距）
      const availableWidth = screenWidth - 32 // 左右各16px padding

      if (textWidth > availableWidth) {
        textScale.value = Math.max(0.7, availableWidth / textWidth) // 最小不低於0.7倍
      } else {
        textScale.value = 1
      }
    }

    const basePath = computed(() => import.meta.env.BASE_URL || '/')

    // 裝置檢測邏輯
    const detectIOSDevice = () => {
      const userAgent = navigator.userAgent.toLowerCase()
      const isIOS = /iphone|ipad|ipod/.test(userAgent)
      const isLineApp = /line/.test(userAgent)
      const isChrome = /crios/.test(userAgent)
      const isSafari = /safari/.test(userAgent) && !/chrome/.test(userAgent)

      // 測試模式支援
      const urlParams = new URLSearchParams(window.location.search)
      const isTestMode = urlParams.get('test-mov') === '1'

      return (isIOS && (isLineApp || isChrome || isSafari)) || isTestMode
    }

    const isIOSDevice = ref(detectIOSDevice())

    // 月亮影片來源（iOS 用 MOV，Android 用 WebM）
    const moonVideoSrc = computed(() => {
      return isIOSDevice.value
        ? basePath.value + 'moon_alpha_ios.mov'
        : basePath.value + 'moon.webm'
    })

    // ✅ 核心：保險喚醒月亮影片
    const ensureMoonPlaying = async () => {
      const v = moonVideo.value
      if (!v) return
      try {
        // 來源沒設就設一次
        if (!v.src) v.src = moonVideoSrc.value

        // 沒 data 先等到 canplay
        if (v.readyState < 2) {
          await new Promise((res) => {
            const onReady = () => { v.removeEventListener('canplay', onReady); res() }
            v.addEventListener('canplay', onReady, { once: true })
          })
        }
        // Safari/iOS 常要 reset currentTime 再播
        if (v.paused || v.ended) {
          try { v.currentTime = 0 } catch {}
          await v.play()
        }
      } catch (e) {
        // 月亮影片播放失敗時的靜默處理
      }
    }

    // 對外暴露：父層用 ref 可以呼叫
    expose({ moonVideo, ensureMoonPlaying, bgCanvas, maskCanvas, outputCanvas })

    // 組件掛載：提示字淡出 + 設 src + 計算文字縮放
    onMounted(() => {
      setTimeout(() => {
        hintVisible.value = false
        setTimeout(() => { showHintText.value = false }, 500)
      }, 10000)

      if (moonVideo.value && !moonVideo.value.src) {
        moonVideo.value.src = moonVideoSrc.value
      }

      // 計算初始文字縮放
      calculateTextScale()

      // 監聽窗口大小變化
      window.addEventListener('resize', calculateTextScale)
    })

    // 清理監聽器
    onBeforeUnmount(() => {
      window.removeEventListener('resize', calculateTextScale)
    })

    // 🔁 條件一到位就嘗試播放（相機在跑 + 需要月亮）
    watch(
      () => [props.backgroundType, props.cameraRunning],
      async ([bg, running]) => {
        const needMoon = ['moon_video', 'custom_moon_bg', 'person_overlay'].includes(bg)
        if (running && needMoon) await ensureMoonPlaying()
      },
      { immediate: true }
    )

    // App 回前景再喚醒一次（常見需求）
    if (typeof document !== 'undefined') {
      document.addEventListener('visibilitychange', () => {
        if (!document.hidden) {
          const needMoon = ['moon_video','custom_moon_bg','person_overlay'].includes(props.backgroundType)
          if (props.cameraRunning && needMoon) {
            ensureMoonPlaying()
          }
        }
      })
    }

    return {
      stage, bgCanvas, maskCanvas, outputCanvas, moonVideo,
      showShareButton, showDownloadButton, showHintText, hintVisible,
      basePath, shutterIcon, moonVideoSrc, textScale,
      backgroundType: props.backgroundType,
      isIOSDevice,
      showControls, cameraRunning
    }
  }
}
</script>